              </div>

              <div className="flex items-center justify-end gap-2">
                <button
                  onClick={() => {}}
                  className="p-2 hover:bg-white/10 rounded-lg transition text-white/60 hover:text-white/90"
                >
                  <Share2 className="h-5 w-5" />
                </button>
                <button
                  onClick={() => {}}
                  className="p-2 hover:bg-white/10 rounded-lg transition text-white/60 hover:text-white/90"
