              <div className="space-y-4 sm:space-y-5">
                {sessionData.exercises.map((exercise, idx) => (
                  <ExerciseSection key={idx} name={exercise.name} sets={exercise.sets} />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
